import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

// Note: quote premiums below include the 10 % first-insurance surcharge
// (every quoted item is a first insurance) and the 5 G processing fee.

describe("MHPCO Claim Office", () => {
  describe("quote", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet / staff / potion → 71 G / 93 G / 49 G (60/80/40 base + 10 % + 5)");
    it.todo("2 runes → 50 G base premium → 60 G");
    it.todo("3 runes → 60 G base premium (block applies) → 71 G");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3) → 115 G");
    it.todo("7 runes → 175 G base premium → 197.5 G rounded up to 198 G");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types) → 88 G");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → 137 G");
    it.todo("cursed sword for a newcomer → 100 + 50 curse + 10 first insurance + 5 fee = 165 G");
    it.todo("cursed sword + plain amulet → curse applies only to sword: 160 + 50 + 16 + 5 = 231 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → 145 G");
    it.todo("cursed sword with exactly enchantment 5 → both surcharges apply → 195 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge → 115 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → 165 G");
    it.todo("customer with exactly 2 years → loyalty discount applies: 100 − 20 + 10 + 5 = 95 G");
    it.todo("long-standing customer's second quote, cursed sword enchantment 7 → 160 G");
    it.todo("unknown item type (broomstick) → throws an error");
  });

  describe("claim", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G, remaining cap 1600 G");
    it.todo("rune, damage 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("payout calculation yielding 350.5 G → 350 G (rounded down)");
    it.todo("sword (500 G) and amulet (300 G) damaged → deductible per item → payout 600 G");
    it.todo("sword + amulet policy → insurance sum 1600 G, cap 3200 G");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords → cap 4000 G; two sword damages each with own deductible");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 G then 600 G, remaining cap 600 G then 0 G");
    it.todo("more damage entries of a type than insured items → throws, whole claim rejected");
    it.todo("damage to an item not in the policy (amulet when only sword insured) → throws");
    it.todo("damage to an unknown item type → throws");
    it.todo("damage entry with negative amount → throws");
  });

  describe("scenario", () => {
    it.todo("schema example: amulet quote for 5-year customer then fire claim → results in step order");
  });
});

