export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

export type QuoteStep = { op: "quote"; items: Item[] };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

const BASE_PREMIUM_PER_ITEM = 100;
const PROCESSING_FEE = 5;

// 10 % surcharge; division avoids floating-point error from `* 0.1`.
const firstInsuranceSurcharge = (basePremium: number): number => basePremium / 10;

export const processScenario = (scenario: Scenario): { results: Result[] } => {
  const basePremium = scenario.steps[0].items.length * BASE_PREMIUM_PER_ITEM;
  const premium = basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
  return { results: [{ premium }] };
};

