  COMPONENT_TYPES.filter((type) => countOfType(items, type) === COMPONENT_BLOCK_SIZE).reduce(
    (discount, type) =>
      discount + COMPONENT_BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM,
    0,
  );

const totalBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0) - componentBlockDiscount(items);

// Item-specific modifiers: a percentage of the base premium of each item matching the condition.
const itemSurcharge =
  (appliesTo: (item: Item) => boolean, percent: number) =>
  (items: Item[]): number =>
    items
      .filter(appliesTo)
      .reduce((sum, item) => sum + percentOf(basePremiumOf(item), percent), 0);

const curseSurcharge = itemSurcharge((item) => item.cursed === true, 50);

const highEnchantmentSurcharge = itemSurcharge((item) => (item.enchantment ?? 0) >= 5, 30);

const quotePremium = (items: Item[], yearsWithMHPCO: number): number => {
  const basePremium = totalBasePremium(items);
  // Only the final amount is rounded — up, in the MHPCO's favor.
  return Math.ceil(
