      highEnchantmentSurcharge(items) +
      firstInsuranceSurcharge(basePremium) -
      loyaltyDiscount(basePremium, yearsWithMHPCO) +
      PROCESSING_FEE,
  );
};

export const processScenario = (scenario: Scenario): { results: Result[] } => ({
  results: [{ premium: quotePremium(scenario.steps[0].items, scenario.customer.yearsWithMHPCO) }],
});

