export const processScenario = ({ customer, steps }: Scenario): { results: Result[] } => ({
  results: steps.map((step, index) =>
    step.op === "claim"
      ? claimResult(step)
      : quoteResult(step, customer.yearsWithMHPCO, hasEarlierQuote(steps, index)),
  ),
});

