// Claims
// ---------------------------------------------------------------------------

const DEDUCTIBLE = 100;

const INSURANCE_VALUES: Record<string, number> = { sword: 1000, rune: 250 };

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const COVERAGE_CAP_MULTIPLIER = 2;
const coverageCap = (items: Item[]): number => COVERAGE_CAP_MULTIPLIER * insuranceSum(items);

const payoutFor = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimResult = (step: ClaimStep, policyItems: Item[]): Result => {
  const payout = step.incident.damages.reduce((sum, damage) => sum + payoutFor(damage), 0);
  return { payout, remainingCap: coverageCap(policyItems) - payout };
};

// ---------------------------------------------------------------------------
// Scenario
// ---------------------------------------------------------------------------

// A claim references its policy by the index of the quote step that created it.
const insuredItemsOf = (steps: Step[], claim: ClaimStep): Item[] =>
  (steps[claim.policy] as QuoteStep).items;

export const processScenario = ({ customer, steps }: Scenario): { results: Result[] } => ({
  results: steps.map((step, index) =>
    step.op === "claim"
      ? claimResult(step, insuredItemsOf(steps, step))
      : quoteResult(step, customer.yearsWithMHPCO, hasEarlierQuote(steps, index)),
  ),
});

